# ---------- validation + merge ----------
def validate(name, raw):
    """returns (df or None, [(severity, issue, detail)])"""
    P = []
    try: df = pd.read_csv(io.BytesIO(raw), dtype=str, encoding="utf-8-sig")
    except Exception as e: return None, [("ERROR", "Could not read the file", str(e)[:200])]
    df.columns = [c.strip() for c in df.columns]
    if df.empty: return None, [("ERROR", "File faka (no data rows)", "")]
    miss, extra = [c for c in COLS if c not in df.columns], [c for c in df.columns if c not in COLS]
    if miss: P.append(("ERROR", "Column missing", ", ".join(miss)))
    if extra: P.append(("ERROR", "Extra/unknown column", ", ".join(extra)))
    if miss: return None, P
    for c in NUM:
        n = pd.to_numeric(df[c], errors="coerce"); bad = n.isna() & df[c].notna()
        if bad.any(): P.append(("ERROR", f"Column '{c}' contains non-numeric values", f"{bad.sum()} rows, first at row {bad.idxmax()+2}: '{df.loc[bad.idxmax(), c]}'"))
        df[c] = n
    dt = pd.to_datetime(df["stock_date"], format=DFMT, errors="coerce"); bad = dt.isna()
    if bad.any(): P.append(("ERROR", "Invalid stock_date format (expected M/D/YYYY h:mm:ss AM/PM)", f"{bad.sum()} rows, first at row {bad.idxmax()+2}: '{df.loc[bad.idxmax(), 'stock_date']}'"))
    if any(p[0] == "ERROR" for p in P): return None, P
    nulls = df[TXT + NUM].isna().sum(); nulls = nulls[nulls > 0]
    if len(nulls): P.append(("WARNING", "Blank values found, treated as 0", "; ".join(f"{k}: {v}" for k, v in nulls.items())))
    df[NUM] = df[NUM].fillna(0).astype(int); df[TXT] = df[TXT].fillna("")
    mm = (df[SIZES].sum(axis=1) != df["TOTAL"]).sum()
    if mm: P.append(("WARNING", "TOTAL does not match the sum of sizes", f"{mm} rows"))
    dup = df.duplicated(["SHOPID", "ARTICLE", "BATCH", "stock_date"]).sum()
    if dup: P.append(("WARNING", "Duplicate row (SHOPID+ARTICLE+BATCH)", f"{dup} rows"))
    df["stock_date"] = dt
    return df, P

def merge(files):
    good, notice = [], []
    for name, raw in files:
        df, P = validate(name, raw)
        notice += [(name, *p) for p in P]
        if df is not None:
            good.append(df)
            if not P: notice.append((name, "OK", "Format is correct", f"{len(df)} rows merged"))
            else: notice.append((name, "MERGED", "Merged with warnings", f"{len(df)} rows"))
        else: notice.append((name, "REJECTED", "Format problem, not merged", ""))
    if good:
        al = pd.concat(good, ignore_index=True); al["d"] = al["stock_date"].dt.date
        for d, g in al.groupby("d"): g.drop(columns="d").to_pickle(os.path.join(DAILY, f"{d}.pkl"))
    json.dump({"at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "rows": notice}, open(NF, "w"))
    return notice

def dates(): return sorted(os.path.basename(p)[:-4] for p in glob.glob(os.path.join(DAILY, "*.pkl")))
def process(df):
    """MERCHAN_CATEGORY bad -> Article diye Brand/Category vlookup -> filter -> Disc/E-Commerce/90000M0 bad"""
    df = df.drop(columns="MERCHAN_CATEGORY"); k = nz(df.ARTICLE)
    keep = ~nz(df.SHOPNAME).str.startswith("DISC") & (nz(df.AREANAME) != "E-COMMERCE") & ~k.str.startswith("90000M0")
    df = df[keep].assign(_k=k[keep])
    if not os.path.exists(MAP): return pd.DataFrame(columns=OUT)
    df = df.merge(pd.read_pickle(MAP), on="_k", how="left")
    df = df[nz(df["Brand Name"]).isin(BRANDS) & nz(df["Merchant Category"]).isin(CATS)]
    return df[OUT].reset_index(drop=True)

def load(d): return process(pd.read_pickle(os.path.join(DAILY, d + ".pkl")))

def merge_map(files):
    """folder theke Brand Name + Merchant Category file (csv/xlsx), Article column diye"""
    parts, notice = [], []; key = lambda c: "".join(ch for ch in str(c).upper() if ch.isalnum())
    for name, raw in files:
        try: df = pd.read_excel(io.BytesIO(raw), dtype=str) if name.lower().endswith((".xlsx", ".xls")) else pd.read_csv(io.BytesIO(raw), dtype=str, encoding="utf-8-sig")
        except Exception as e: notice.append((name, "REJECTED", "Could not read the file", str(e)[:200])); continue
        cm = {key(c): c for c in df.columns}
        col = {"ARTICLE": cm.get("ARTICLE"), "Brand Name": cm.get("BRANDNAME"), "Merchant Category": cm.get("MERCHANTCATEGORY") or cm.get("MERCHANCATEGORY")}
        miss = [k for k, v in col.items() if v is None]
        if miss: notice.append((name, "REJECTED", "Column missing", ", ".join(miss) + " | pelam: " + ", ".join(map(str, df.columns)))); continue
        df = df[[col["ARTICLE"], col["Brand Name"], col["Merchant Category"]]]; df.columns = ["ARTICLE", "Brand Name", "Merchant Category"]
        parts.append(df); notice.append((name, "OK", "Mapping file loaded", f"{len(df)} rows"))
    if parts:
        m = pd.concat(parts, ignore_index=True).fillna(""); m["_k"] = nz(m.ARTICLE)
        for c in ("Brand Name", "Merchant Category"): m[c] = m[c].astype(str).str.strip()
        dup = m.duplicated("_k").sum(); m = m.drop_duplicates("_k", keep="first")
        if dup: notice.append(("(all mapping files)", "WARNING", "Duplicate Article found, first one kept", f"{dup} rows"))
        m[["_k", "Brand Name", "Merchant Category"]].to_pickle(MAP)
        json.dump({"at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "rows": len(m), "files": [x[0] for x in files]}, open(os.path.join(D, "mapping_meta.json"), "w"))
    return notice

