# ---------- QR code (offline, pure python, byte mode, level M, version 1-6) ----------
def qr_svg(text):
    data = text.encode(); T6 = {1: (16, 10, 1), 2: (28, 16, 1), 3: (44, 26, 1), 4: (64, 18, 2), 5: (86, 24, 2), 6: (108, 16, 4)}
    v = next((k for k, (dc, ec, nb) in T6.items() if len(data) + 2 <= dc), 0)
    if not v: return ""
    dc, ec, nb = T6[v]; sz = 17 + 4 * v
    bits = "0100" + format(len(data), "08b") + "".join(format(b, "08b") for b in data); bits += "0" * min(4, dc * 8 - len(bits)); bits += "0" * (-len(bits) % 8)
    cw = [int(bits[i:i + 8], 2) for i in range(0, len(bits), 8)]; cw += [0xEC, 0x11] * dc; cw = cw[:dc]
    EX, LG, x = [0] * 512, [0] * 256, 1
    for i in range(255):
        EX[i] = x; LG[x] = i; x <<= 1; x ^= 0x11D if x & 256 else 0
    for i in range(255, 512): EX[i] = EX[i - 255]
    mul = lambda a, b: 0 if not a or not b else EX[LG[a] + LG[b]]
    g = [1]
    for i in range(ec):
        ng = [0] * (len(g) + 1)
        for j, c in enumerate(g): ng[j] ^= c; ng[j + 1] ^= mul(c, EX[i])
        g = ng
    def rs(blk):
        r = [0] * ec
        for b in blk:
            f = b ^ r[0]; r = r[1:] + [0]
            if f: r = [r[j] ^ mul(g[j + 1], f) for j in range(ec)]
        return r
    n = dc // nb; blocks = [cw[i * n:(i + 1) * n] for i in range(nb)]; ecs = [rs(b) for b in blocks]
    fin = [blk[i] for i in range(n) for blk in blocks] + [e[i] for i in range(ec) for e in ecs]
    allb = "".join(format(b, "08b") for b in fin) + "0" * (7 if v > 1 else 0)
    M = [[False] * sz for _ in range(sz)]; F = [[False] * sz for _ in range(sz)]
    def st(x, y, d): M[y][x] = d; F[y][x] = True
    for i in range(sz): st(6, i, i % 2 == 0); st(i, 6, i % 2 == 0)
    for cx, cy in ((3, 3), (sz - 4, 3), (3, sz - 4)):
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                if 0 <= cx + dx < sz and 0 <= cy + dy < sz: st(cx + dx, cy + dy, max(abs(dx), abs(dy)) not in (2, 4))
    if v > 1:
        for dy in range(-2, 3):
            for dx in range(-2, 3): st(sz - 7 + dx, sz - 7 + dy, max(abs(dx), abs(dy)) != 1)
    for i in range(9): F[8][i] = F[i][8] = True
    for i in range(8): F[8][sz - 1 - i] = F[sz - 1 - i][8] = True
    F[sz - 8][8] = True; M[sz - 8][8] = True
    i = 0
    for right in range(sz - 1, 0, -2):
        right = 5 if right == 6 else right
        for vert in range(sz):
            for j in range(2):
                xx = right - j; yy = sz - 1 - vert if ((right + 1) & 2) == 0 else vert
                if not F[yy][xx] and i < len(allb): M[yy][xx] = allb[i] == "1"; i += 1
    conds = [lambda x, y: (x + y) % 2 == 0, lambda x, y: y % 2 == 0, lambda x, y: x % 3 == 0, lambda x, y: (x + y) % 3 == 0, lambda x, y: (x // 3 + y // 2) % 2 == 0,
             lambda x, y: x * y % 2 + x * y % 3 == 0, lambda x, y: (x * y % 2 + x * y % 3) % 2 == 0, lambda x, y: ((x + y) % 2 + x * y % 3) % 2 == 0]
    def fmt(m):
        d = m; r = d << 10
        for k in range(4, -1, -1):
            if (r >> (k + 10)) & 1: r ^= 0x537 << k
        return ((d << 10) | r) ^ 0x5412
    def build(m):
        Q = [row[:] for row in M]; fb = fmt(m); b = lambda k: (fb >> k) & 1 == 1
        for y in range(sz):
            for x in range(sz):
                if not F[y][x] and conds[m](x, y): Q[y][x] = not Q[y][x]
        for k in range(6): Q[k][8] = b(k)
        Q[7][8], Q[8][8], Q[8][7] = b(6), b(7), b(8)
        for k in range(9, 15): Q[8][14 - k] = b(k)
        for k in range(8): Q[8][sz - 1 - k] = b(k)
        for k in range(8, 15): Q[sz - 15 + k][8] = b(k)
        Q[sz - 8][8] = True; return Q
    def pen(Q):
        p = 0
        for L in (Q, list(zip(*Q))):
            for row in L:
                run = 1
                for a, c in zip(row, row[1:]):
                    run = run + 1 if a == c else 1
                    p += 3 if run == 5 else 1 if run > 5 else 0
        return p + 3 * sum(Q[y][x] == Q[y][x + 1] == Q[y + 1][x] == Q[y + 1][x + 1] for y in range(sz - 1) for x in range(sz - 1))
    Q = min((build(m) for m in range(8)), key=pen); q = 4
    path = "".join(f"M{x+q},{y+q}h1v1h-1z" for y in range(sz) for x in range(sz) if Q[y][x])
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {sz+2*q} {sz+2*q}" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="#fff"/><path d="{path}"/></svg>'

