def lan_ip():
    import socket
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as k: k.connect(("10.255.255.255", 1)); return k.getsockname()[0]
    except Exception: return ""

def site_base():
    base = os.environ.get("PUBLIC_URL", "").rstrip("/") or request.url_root.rstrip("/")
    loop = any(h in base for h in ("127.0.0.1", "localhost"))
    if loop and os.environ.get("HOST", "0.0.0.0") != "127.0.0.1" and lan_ip(): base, loop = f"http://{lan_ip()}:{os.environ.get('PORT', 5000)}", False
    return base, loop

