def local_setup():
    """Shortcut for the computer that runs the app: it starts the app (if not running) and opens it in its own window."""
    frozen = getattr(sys, "frozen", False); appdir = os.path.dirname(os.path.abspath(sys.executable if frozen else __file__))
    pw = os.path.join(os.path.dirname(sys.executable), "pythonw.exe")      # windowed Python: no console
    t = sys.executable if frozen or not os.path.exists(pw) else pw; v = "" if frozen else os.path.join(appdir, "app.py")
    return LOCAL_SETUP.replace("@@T@@", t).replace("@@V@@", v).replace("@@W@@", appdir).replace("@@I@@", os.path.join(D, "Apex.ico"))

@app.route("/download/setup.bat")
def setup_bat():
    if request.remote_addr in ("127.0.0.1", "::1"):
        return app.response_class(local_setup().replace("\n", "\r\n"), mimetype="application/octet-stream",
                                  headers={"Content-Disposition": "attachment; filename=Apex_Retail_Broken_Size_Analysis_Setup.bat"})
    base, _ = site_base()
    return app.response_class(SETUP.replace("@@URL@@", base).replace("\n", "\r\n"), mimetype="application/octet-stream",
                              headers={"Content-Disposition": "attachment; filename=Apex_Retail_Broken_Size_Analysis_Setup.bat"})

