RC = ["SHOPID", "SHOPNAME", "AREANAME", "ARTICLE", "Brand Name", "MERCHAN_CATEGORY", "Price", "Stock Qty (Prs/Pcs)", "Stock Value (BDT)", "Size Status",
      "Number of Sizes Available", "BATCH", "Available Size No", "Available Size Qty"] + SIZES + ["Date"]   # attached Report.xlsx ("Details") er moto
BROKEN_MAX = 3   # stock thaka size <= 3 hole "Broken Size", 4+ hole "Regular Size"

def report(d):
    """Daily Stock (filtered) -> Shop+Article wise 1 row. Disk cache: data/rep_<d>.pkl"""
    p, cp = os.path.join(DAILY, d + ".pkl"), os.path.join(D, f"rep2_{d}.pkl")
    sig = max(os.path.getmtime(p), os.path.getmtime(MAP) if os.path.exists(MAP) else 0)
    if os.path.exists(cp) and os.path.getmtime(cp) > sig: return pd.read_pickle(cp)
    df = load(d); df = df[df.TOTAL > 0]; k = ["SHOPID", "ARTICLE"]
    bt = df.drop_duplicates(k + ["BATCH"]).assign(BATCH=lambda x: x.BATCH.astype(str)).groupby(k, sort=False).BATCH.agg(",".join)   # batch: order of first appearance
    g = df.groupby(k, sort=False).agg({"SHOPNAME": "first", "AREANAME": "first", "Brand Name": "first", "Merchant Category": "first", "MRP": "first",
                                       "stock_date": "first", **{x: "sum" for x in SIZES}}).join(bt).reset_index()
    q = g[SIZES].values; has = q > 0
    g["Price"], g["Stock Qty (Prs/Pcs)"] = g.MRP, q.sum(1); g["Stock Value (BDT)"] = g.Price * g["Stock Qty (Prs/Pcs)"]
    g["Number of Sizes Available"] = has.sum(1)
    g["Size Status"] = ["Broken Size" if n <= BROKEN_MAX else "Regular Size" for n in g["Number of Sizes Available"]]
    g["Available Size No"] = [",".join(z for z, h in zip(SIZES, r) if h) for r in has]
    g["Available Size Qty"] = [",".join(str(v) for v, h in zip(r, hh) if h) for r, hh in zip(q, has)]
    g["MERCHAN_CATEGORY"], g["Date"] = g["Merchant Category"], g.stock_date.dt.normalize()
    g["SHOPNAME"], g["AREANAME"] = g.SHOPNAME.str.upper(), g.AREANAME.str.upper()   # Report-e upper case
    g = g.sort_values("SHOPID", kind="stable").reset_index(drop=True)[RC]   # Shop code ascending (Report.xlsx er moto)
    g.to_pickle(cp); return g

KINDS = {"daily": ("Daily Stock", load, OUT), "report": ("Report", report, RC)}
_cnt = {}
def count(kind, d):
    p = os.path.join(DAILY, d + ".pkl"); m = (os.path.getmtime(p), os.path.getmtime(MAP) if os.path.exists(MAP) else 0)
    if _cnt.get((kind, d), (0, 0))[0] != m: _cnt[kind, d] = (m, len(KINDS[kind][1](d)))
    return _cnt[kind, d][1]

