def picked(latest=False):
    f, t, ds = request.args.get("from", ""), request.args.get("to", ""), dates()
    if latest and not f and not t: return ds[-1:]
    return [d for d in ds if (not f or d >= f) and (not t or d <= t)]

def view(df, cols):
    df = df[cols].copy(); c = "Date" if "Date" in cols else "stock_date"
    df[c] = df[c].dt.strftime(DFMT) if c == "stock_date" else df[c].dt.strftime("%d-%b-%y"); return df

FILTER = """<form>From <select name=from><option value=''>All</option>{%for x in ds%}<option {{'selected' if x==f}}>{{x}}</option>{%endfor%}</select>
To <select name=to><option value=''>All</option>{%for x in ds%}<option {{'selected' if x==t}}>{{x}}</option>{%endfor%}</select> <button>Filter</button>
<a class=btn href='/dl/{{kind}}.xlsx?{{qs}}'>Excel Download</a></form>"""
def ctx(kind):
    q = request.args.to_dict(); q.pop("p", None)
    return dict(ds=dates(), f=request.args.get("from", ""), t=request.args.get("to", ""), kind=kind, qs="&".join(f"{k}={v}" for k, v in q.items()))
def ready():
    if not dates(): return page("<div class=c>No data uploaded yet.</div>")
    if not os.path.exists(MAP): return page("<div class=c>First upload the <b>Brand Name &amp; Merchant Category</b> folder from the Upload page (it is saved after one upload).</div>")

def grid(kind):
    r = need() or ready()
    if r: return r
    title, loader, cols = KINDS[kind]; sel, PS = picked(), 100
    cn = {d: count(kind, d) for d in sel}; total = sum(cn.values()); pg = max(1, int(request.args.get("p", 1)))
    off, parts = (pg - 1) * PS, []
    for d in sel:                       # one date below another
        if off >= cn[d]: off -= cn[d]; continue
        parts.append(loader(d).iloc[off:off + PS - sum(map(len, parts))]); off = 0
        if sum(map(len, parts)) >= PS: break
    tb = view(pd.concat(parts), cols).to_html(index=False, border=0) if parts else "No rows"; c = ctx(kind)
    return page("<div class=c>" + FILTER + """<p><b>{{title}}</b> - {{sel|length}} date, <b>{{'{:,}'.format(total)}}</b> row
{%for d in sel%}<span style='margin:0 10px 0 0;font-size:12px'>{{d}}: {{'{:,}'.format(cn[d])}}</span>{%endfor%}</p>
Page {{pg}} / {{pages}} &nbsp; {%if pg>1%}<a href='?{{qs}}&p={{pg-1}}'>&laquo; Prev</a>{%endif%} {%if pg<pages%}<a href='?{{qs}}&p={{pg+1}}'>Next &raquo;</a>{%endif%}</div>
<div class=c style='overflow:auto;max-height:70vh;padding:0'><div class=xl>{{tb|safe}}</div></div>""", sel=sel, cn=cn, total=total, pg=pg, pages=max(1, -(-total // PS)), tb=tb, title=title, **c)

CATD = {c.upper(): c for c in ["EVA", "Flip Flop", "Children Twinkler", "Ladies Moochie", "Sports Shoe", "Ladies Nino Rossi", "Men Sandal Venturini", "Canvas", "Sports Sandal", "PVC",
        "Men Shoe Venturini", "Ladies Dr. Mauch", "Men Sandal Apex", "FeelLight", "Men Shoe Apex", "Men Shoe Maverick", "Men Sandal Dr. Mauch", "School"]}   # Summary file-er lekha (category naam)

def summ(d):
    """Summary tables (Summary.xlsx er moto) - Report(d) theke"""
    g = report(d); b = g["Size Status"] == "Broken Size"; q, v = g["Stock Qty (Prs/Pcs)"], g["Stock Value (BDT)"]
    g = g.assign(B=b.astype(int), BQ=q * b, BV=v * b)
    def roll(by, pct=True):
        r = g.groupby(by, sort=False).agg(art=("ARTICLE", "size"), qty=("Stock Qty (Prs/Pcs)", "sum"), val=("Stock Value (BDT)", "sum"),
                                          ba=("B", "sum"), bq=("BQ", "sum"), bv=("BV", "sum")).reset_index()
        r.columns = [f"k{i}" for i in range(len(by))] + list(r.columns[len(by):])
        r["pa"], r["pq"], r["pv"] = r.ba / r.art, r.bq / r.qty, r.bv / r.val
        return (r.sort_values("pa", ascending=False, kind="stable") if pct else r.sort_values("k0", kind="stable")).reset_index(drop=True)
    st = g.groupby("Size Status").agg(art=("ARTICLE", "size"), qty=("Stock Qty (Prs/Pcs)", "sum"), val=("Stock Value (BDT)", "sum"))
    z = lambda k: [int(st.loc[k, c]) if k in st.index else 0 for c in ("art", "qty", "val")]
    return dict(d=d, reg=z("Regular Size"), brk=z("Broken Size"), brand=roll(["Brand Name"]), cat=roll(["MERCHAN_CATEGORY"]).assign(k0=lambda t: t.k0.map(lambda x: CATD.get(str(x).upper(), x))),
                area=roll(["AREANAME"]), top=roll(["SHOPID", "SHOPNAME", "AREANAME"]).head(30), shop=roll(["SHOPID", "SHOPNAME", "AREANAME"], False))   # Top 30 outlet = % Broken (As per Articles) boro theke chhoto

H3 = ["No of Article", "Stock Qty (Prs/Pcs)", "Stock Value (BDT)", "% of Broken Size (As per Articles)", "% of Broken Size (As per Stock)", "% of Broken Size (As per Stock Value)"]
NOTE1 = ("1) We have prepared this report excluding the Stock of all discount outlets, E-commerce and E-commerce Market.  The categories of Apparel, Socks, Accessories, "
         "Essentials, Fly, International Brand products, and also the article No: 90000M01 are not included.")
NOTE2 = "2) If the stock of every article in every outlet is below minimum 4 sizes, it will be considered as Broken size; if it is more, it will be considered as regular size."
def dstr(d):
    t = datetime.strptime(d, "%Y-%m-%d"); n = t.day
    return f"{n}{'th' if 10 <= n % 100 <= 20 else {1: 'st', 2: 'nd', 3: 'rd'}.get(n % 10, 'th')} {t:%B %Y}"
def srows(r, names=("k0",)):
    return [[i + 1] + [getattr(x, k) for k in names] + [int(x.art), int(x.qty), int(x.val), float(x.pa), float(x.pq), float(x.pv)] for i, x in enumerate(r.itertuples())]
def orows(r): return [[x.k0, x.k1, x.k2, int(x.art), int(x.qty), int(x.val), float(x.pa), float(x.pq), float(x.pv)] for x in r.itertuples()]

def write_summary(wb, name, S):
    from xlsxwriter.utility import xl_col_to_name as cn
    ws = wb.add_worksheet(name); F = lambda **k: wb.add_format({"border": 1, "valign": "vcenter", **k}); NF = '_(* #,##0_);_(* \\(#,##0\\);_(* "-"??_);_(@_)'
    f = dict(hd=F(bold=True, align="center", text_wrap=True), txt=F(), ctr=F(align="center"), num=F(num_format=NF, align="center"), pct=F(num_format="0.00%", align="center"),
             tot=F(bold=True, align="center"), tnum=F(bold=True, num_format=NF, align="center"), n0=F(num_format=NF), p0=F(num_format="0.00%"), t0=F(bold=True, num_format=NF), b0=F(bold=True))
    for c, w in zip("ABCDEFGHIJKLMNOPQR", [3.5, 45.1, 11.5, 12.5, 14, 18.3, 18.6, 21.5, 8.7, 7.3, 22.5, 17.5, 18.9, 14, 17.8, 17.8, 17.8, 17.8]): ws.set_column(f"{c}:{c}", w)
    ws.merge_range("B1:L1", "Apex Footwear Ltd", wb.add_format({"bold": True, "font_size": 20, "align": "center"}))
    for r, t in ((2, "Nationwide Retail Broken Size Products Analysis."), (3, "Date: " + dstr(S["d"]))): ws.merge_range(f"B{r}:L{r}", t, wb.add_format({"align": "center"}))
    ws.write("A5", "1) Retail Outlet Wise Broken Size Products Status"); ws.set_row(6, 43.5)
    ws.write_row("B7", ["Details", "Total Article", "Stock Qty (Prs/Pcs)", "Stock Value (BDT)", "% of Broken/Regular Size (As per Articles)", "% of Broken/Regular Size (As per Stock)",
                        "% of Broken/Regular Size (As per Stock Value)"], f["hd"])
    tt = [a + b for a, b in zip(S["reg"], S["brk"])]
    for r, lab, v in ((8, "REGULAR SIZE", S["reg"]), (9, "BROKEN SIZE", S["brk"])):
        ws.write(f"B{r}", lab, f["txt"]); [ws.write(r - 1, 2 + j, v[j], f["n0"]) for j in range(3)]
        [ws.write_formula(r - 1, 5 + j, f"={cn(2+j)}{r}/${cn(2+j)}$10", f["p0"], v[j] / max(tt[j], 1)) for j in range(3)]
    ws.write("B10", "Total", f["b0"]); [ws.write_formula(9, 2 + j, f"=SUM({cn(2+j)}8:{cn(2+j)}9)", f["t0"], tt[j]) for j in range(3)]
    [ws.write_formula(9, 5 + j, f"=SUM({cn(5+j)}8:{cn(5+j)}9)", f["p0"], 1 if tt[j] else 0) for j in range(3)]
    def tbl(r0, c0, heads, rows, total):
        ws.write_row(r0 - 1, c0, heads, f["hd"]); ws.set_row(r0 - 1, 29)
        for i, row in enumerate(rows):
            for j, v in enumerate(row): ws.write(r0 + i, c0 + j, v, f["ctr"] if j == 0 and isinstance(v, int) else f["txt"] if isinstance(v, str) else f["pct"] if isinstance(v, float) else f["num"])
        if total:
            t = r0 + len(rows) + 1; ws.merge_range(t - 1, c0, t - 1, c0 + 1, "Total", f["tot"])
            for j in (2, 3, 4): ws.write_formula(t - 1, c0 + j, f"=SUM({cn(c0+j)}{r0+1}:{cn(c0+j)}{r0+len(rows)})", f["tnum"], sum(r[j] for r in rows))
    nb, nc, na = len(S["brand"]), len(S["cat"]), len(S["area"])
    ws.write("A13", "2) Brand wise Broken size percentage (%). "); ws.write("J13", "3) Merchant  Category wise Broken size percentage (%). ")
    tbl(15, 0, ["SL No", "Brand Name"] + H3, srows(S["brand"]), True); tbl(15, 9, ["SL NO", "Merchant Category"] + H3, srows(S["cat"]), True)
    s4 = 16 + max(nb, nc) + 2; ws.write(f"A{s4}", "4) Area wise cut size & regular size percentage (%). "); ws.write(f"J{s4}", "5) Top 30 Outlets Cut size Status. ")
    tbl(s4 + 2, 0, ["SL NO", "Area Name"] + H3, srows(S["area"]), True)
    tbl(s4 + 2, 9, ["Outlet Code", "Outlet Name", "Area Name"] + H3, orows(S["top"]), False)
    n = max(s4 + 2 + na + 1, s4 + 2 + len(S["top"])) + 2
    ws.write(f"B{n}", "Note:", f["b0"]); ws.merge_range(f"B{n+1}:J{n+1}", NOTE1, wb.add_format({"text_wrap": True, "valign": "top"})); ws.set_row(n, 45); ws.write(f"B{n+2}", NOTE2)

def shtml(S):
    fm = lambda v: f"{v:.2%}" if isinstance(v, float) else f"{v:,}" if isinstance(v, int) and not isinstance(v, bool) else v
    def t(heads, rows, tot=0):
        h = "".join(f"<th>{x}</th>" for x in heads); b = "".join("<tr>" + "".join(f"<td>{fm(v)}</td>" for v in r) + "</tr>" for r in rows)
        if tot: b += "<tr><th colspan=2>Total</th>" + "".join(f"<th>{sum(r[j] for r in rows):,}</th>" for j in (2, 3, 4)) + "<th></th>" * 3 + "</tr>"
        return f"<table><tr>{h}</tr>{b}</table>"
    tt = [a + b for a, b in zip(S["reg"], S["brk"])]; st = [["REGULAR SIZE"] + S["reg"] + [S["reg"][j] / max(tt[j], 1) for j in range(3)], ["BROKEN SIZE"] + S["brk"] + [S["brk"][j] / max(tt[j], 1) for j in range(3)],
                                                           ["Total"] + tt + [1.0] * 3]
    st = [[r[0]] + r[1:4] + r[4:] for r in st]
    sec = lambda title, body: f"<div class=c><h3>{title}</h3><div style='overflow:auto;max-height:60vh'>{body}</div></div>"
    return (f"<div class=c style='text-align:center'><h2 style='margin:0'>Apex Footwear Ltd</h2>Nationwide Retail Broken Size Products Analysis.<br>Date: {dstr(S['d'])}</div>"
            + sec("1) Retail Outlet Wise Broken Size Products Status", t(["Details", "Total Article", "Stock Qty (Prs/Pcs)", "Stock Value (BDT)", "% of Broken/Regular Size (As per Articles)", "% of Broken/Regular Size (As per Stock)", "% of Broken/Regular Size (As per Stock Value)"], st))
            + "<div style='display:grid;grid-template-columns:1fr 1fr;gap:16px'>"
            + sec("2) Brand wise Broken size percentage (%)", t(["SL No", "Brand Name"] + H3, srows(S["brand"]), 1))
            + sec("3) Merchant Category wise Broken size percentage (%)", t(["SL NO", "Merchant Category"] + H3, srows(S["cat"]), 1))
            + sec("4) Area wise cut size &amp; regular size percentage (%)", t(["SL NO", "Area Name"] + H3, srows(S["area"]), 1))
            + sec("5) Top 30 Outlets Cut size Status", t(["Outlet Code", "Outlet Name", "Area Name"] + H3, orows(S["top"]))) + "</div>"
            + f"<div class=c><b>Note:</b><br>{NOTE1}<br>{NOTE2}</div>")

