# ---------- Monthly Summary ----------
def ordn(n): return f"{n}{'th' if 10 <= n % 100 <= 20 else {1: 'st', 2: 'nd', 3: 'rd'}.get(n % 10, 'th')}"
def period(ds):
    a, b = (datetime.strptime(x, "%Y-%m-%d") for x in (ds[0], ds[-1]))
    return f"Period: {ordn(a.day)} {a:%b} to {ordn(b.day)}{'' if (a.month, a.year) == (b.month, b.year) else f' {b:%b}'}-{b.year} ({len(ds):02d} days)"

def msumm(ds):
    """Per-date Summary results -> one table per section: (left cols, average of daily %, daily % per date). Average = mean of the daily percentages."""
    Ss = [summ(d) for d in ds]; n = len(ds)
    mean = lambda v: (sum(v) / len(v)) if v else None
    def tab(key, meta=lambda x: ()):
        rows = {}
        for i, S in enumerate(Ss):
            for x in S[key].itertuples():
                rows.setdefault(x.k0, [meta(x), [None] * n])[1][i] = (float(x.pa), float(x.pq), float(x.pv)); rows[x.k0][0] = meta(x)
        out = [(k, m, tuple(mean([t[j] for t in v if t]) for j in range(3)), v) for k, (m, v) in rows.items()]
        return sorted(out, key=lambda r: -r[2][0])
    st = lambda j, k: [(S[k][0] / max(S["reg"][0] + S["brk"][0], 1), S[k][1] / max(S["reg"][1] + S["brk"][1], 1), S[k][2] / max(S["reg"][2] + S["brk"][2], 1)) for S in Ss]
    stat = [(lab, (), tuple(mean([t[j] for t in v]) for j in range(3)), v) for lab, v in (("REGULAR SIZE", st(0, "reg")), ("BROKEN SIZE", st(0, "brk")))]
    return dict(ds=ds, stat=stat, brand=tab("brand"), cat=tab("cat"), area=tab("area"), top=tab("shop", lambda x: (x.k1, x.k2))[:30])

HEADS3 = ["Articles", "Stock Qty", "Stock Value"]
def msections(M):
    """(title, left headers, rows[(left values, avg, daily)]) - same layout as Monthly_Summary.xlsx"""
    num = lambda rows, f: [(f(i, r), r[2], r[3]) for i, r in enumerate(rows)]
    return [("1) Details of the Total Articles in nationwide retail outlet.", ["Details"], num(M["stat"], lambda i, r: [r[0]])),
            ("2) Brand wise Broken size percentage (%). ", ["SL No", "Brand Name"], num(M["brand"], lambda i, r: [i + 1, r[0]])),
            ("3) Merchant  Category wise Broken size percentage (%). ", ["SL NO", "Merchant Category"], num(M["cat"], lambda i, r: [i + 1, r[0]])),
            ("4) Area wise Broken size percentage (%). ", ["SL NO", "Area Name"], num(M["area"], lambda i, r: [i + 1, r[0]])),
            ("5) Top 30 Outlets Broken size Status. ", ["SL NO", "Outlet Code", "Outlet Name", "Area Name"], num(M["top"], lambda i, r: [i + 1, r[0], r[1][0], r[1][1]]))]

def write_monthly(wb, name, M):
    ws = wb.add_worksheet(name); ds = M["ds"]; n = len(ds); F = lambda **k: wb.add_format({"border": 1, "valign": "vcenter", **k})
    hd, dh, txt, ctr, pct = F(bold=True, align="center", text_wrap=True), F(bold=True, align="center", num_format="d-mmm"), F(), F(align="center"), F(num_format="0.00%", align="center")
    for c, w in [(0, 5), (1, 22), (2, 24), (3, 19)]: ws.set_column(c, c, w)
    ws.set_column(4, 6 + 3 * n, 11)
    ws.merge_range("A1:E1", "Apex Footwear Ltd", wb.add_format({"bold": True, "font_size": 20, "align": "center"}))
    for r, t in ((2, "Retail Broken Size Products Analysis."), (3, period(ds))): ws.merge_range(f"A{r}:E{r}", t, wb.add_format({"align": "center"}))
    r = 5
    for sec, (title, heads, rows) in enumerate(msections(M)):
        c0 = 1 if sec == 0 else 0; ac = c0 + len(heads); ws.write(r - 1, 0, title); h = r + 2
        for j, l in enumerate(heads): ws.merge_range(h - 1, c0 + j, h, c0 + j, l, hd)
        ws.merge_range(h - 1, ac, h - 1, ac + 2, "(%) Average", hd)
        for j, l in enumerate(HEADS3): ws.write(h, ac + j, l, hd)
        for i, d in enumerate(ds):
            c = ac + 3 + 3 * i; ws.merge_range(h - 1, c, h - 1, c + 2, datetime.strptime(d, "%Y-%m-%d"), dh)
            for j, l in enumerate(HEADS3): ws.write(h, c + j, l, hd)
        for k, (left, av, v) in enumerate(rows):
            row = h + 1 + k
            for j, x in enumerate(left): ws.write(row, c0 + j, x, ctr if j == 0 and isinstance(x, int) else txt)
            for j in range(3): ws.write(row, ac + j, av[j], pct)
            for i, t in enumerate(v):
                for j in range(3): ws.write(row, ac + 3 + 3 * i + j, t[j] if t else "", pct)
        r = h + len(rows) + 3

def mhtml(M):
    ds = M["ds"]; p = lambda x: "" if x is None else f"{x:.2%}"
    out = f"<div class=c style='text-align:center'><h2 style='margin:0'>Apex Footwear Ltd</h2>Retail Broken Size Products Analysis.<br>{period(ds)}</div>"
    for title, heads, rows in msections(M):
        hd = "".join(f"<th rowspan=2>{h}</th>" for h in heads) + "<th colspan=3>(%) Average</th>" + "".join(f"<th colspan=3>{datetime.strptime(d, '%Y-%m-%d'):%d-%b}</th>" for d in ds)
        sub = "".join(f"<th>{x}</th>" for x in HEADS3 * (1 + len(ds)))
        body = "".join("<tr>" + "".join(f"<td>{x}</td>" for x in left) + "".join(f"<td>{p(x)}</td>" for x in av) + "".join(f"<td>{p(x)}</td>" for t in v for x in (t or (None,) * 3)) + "</tr>" for left, av, v in rows)
        out += f"<div class=c><h3>{title}</h3><div style='overflow:auto;max-height:65vh'><table><tr>{hd}</tr><tr>{sub}</tr>{body}</table></div></div>"
    return out + "<div class=c><small>Average = mean of the daily percentages of the selected dates. Top 30 Outlets = highest average % of Broken Size (As per Articles).</small></div>"

MFLT = re.sub(r"<small>.*?</small>", "<small>{{sel|length}} date(s) selected: one column group per date, plus the average of the selected dates.</small>", FLT.replace("/dl/summary.xlsx", "/dl/monthly.xlsx"), flags=re.S)

