# ---------- fast Report.xlsx (Details) writer: xlsxwriter skeleton + data rows streamed as raw XML ----------
import hashlib, zipfile
XL_DIR = os.path.join(D, "xlsx_cache"); os.makedirs(XL_DIR, exist_ok=True)
_xl_lock = threading.Lock()
_STR = {0, 1, 2, 3, 4, 5, 9, 11, 12, 13}   # text columns; 7,8 = #,##0 ; 9,10 centered ; 49 = Date

def build_report_xlsx(frames, out):
    import xlsxwriter
    al = pd.concat(frames, ignore_index=True); LIM = 1_048_574; n = len(RC)
    chunks = [al.iloc[i:i + LIM] for i in range(0, max(len(al), 1), LIM)]
    b = io.BytesIO(); wb = xlsxwriter.Workbook(b, {"in_memory": True, "default_date_format": "d-mmm-yy"})
    NF = '_(* #,##0_);_(* \\(#,##0\\);_(* "-"??_);_(@_)'; B = lambda **k: wb.add_format({"border": 1, **k})
    base, num, ctr, dtf, hd = B(), B(num_format=NF, align="center"), B(align="center"), B(num_format="d-mmm-yy"), B(bold=True)
    tn, t0 = wb.add_format({"bold": True, "num_format": NF, "align": "center"}), wb.add_format({"bold": True, "num_format": NF})
    W = [7.3, 24.7, 17.5, 9.8, 14.6, 20, 5.8, 16.8, 15.7, 10.7, 22.5, 10.2, 25.3, 25.3] + [7.6] * 35 + [10]
    for k, ch in enumerate(chunks):
        ws = wb.add_worksheet("Details" if k == 0 else f"Details {k+1}"); last = len(ch) + 2
        for j, w in enumerate(W): ws.set_column(j, j, w)
        ws.freeze_panes(2, 0); ws.autofilter(1, 0, last - 1, n - 1)
        ws.write_formula(0, 3, f"=SUBTOTAL(3,D3:D{last})", t0, len(ch))
        for j in [7, 8, 10] + list(range(14, 49)): ws.write_formula(0, j, f"=SUBTOTAL(9,{xl_col(j)}3:{xl_col(j)}{last})", tn, int(ch[RC[j]].sum()))
        ws.write_row(1, 0, RC, hd)
        if k == 0: ws.write(2, 0, "x", base); ws.write_number(2, 1, 1, num); ws.write_number(2, 2, 1, ctr); ws.write_datetime(2, 3, pd.Timestamp("2026-01-01").to_pydatetime(), dtf)   # probe row -> style ids
    wb.close(); skel = zipfile.ZipFile(io.BytesIO(b.getvalue()))
    s1 = skel.read("xl/worksheets/sheet1.xml").decode()
    sid = {nm: int(re.search(rf'<c r="{c}3" s="(\d+)"', s1).group(1)) for nm, c in (("base", "A"), ("num", "B"), ("ctr", "C"), ("dt", "D"))}
    epoch = pd.Timestamp("1899-12-30"); esc = lambda v: v.str.replace("&", "&amp;", regex=False).str.replace("<", "&lt;", regex=False).str.replace(">", "&gt;", regex=False)
    tpl = []
    for j in range(n):
        L = xl_col(j)
        if j in _STR: tpl.append(f'<c r="{L}%d" s="{sid["ctr" if j == 9 else "base"]}" t="inlineStr"><is><t>%s</t></is></c>')
        else: tpl.append(f'<c r="{L}%d" s="{sid["dt" if j == 49 else "num" if j in (7, 8) else "ctr" if j == 10 else "base"]}"><v>%d</v></c>')
    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED, compresslevel=1) as zf:
        for item in skel.infolist():
            data = skel.read(item.filename); m = re.fullmatch(r"xl/worksheets/sheet(\d+)\.xml", item.filename)
            if not m: zf.writestr(item.filename, data); continue
            ch = chunks[int(m.group(1)) - 1]; x = data.decode(); head, tail = x.split("</sheetData>")
            head = re.sub(r'<row r="3".*?</row>', "", head, flags=re.S) if m.group(1) == "1" else head
            head = re.sub(r'<dimension ref="[^"]*"/>', f'<dimension ref="A1:{xl_col(n-1)}{len(ch)+2}"/>', head)
            with zf.open(item.filename, "w", force_zip64=True) as f:
                f.write(head.encode())
                for st in range(0, len(ch), 20000):
                    sub = ch.iloc[st:st + 20000]; rows = range(st + 3, st + 3 + len(sub)); cols = []
                    for j, c in enumerate(RC):
                        v = sub[c]
                        if j in _STR: v = v.astype(str); v = esc(v) if v.str.contains("[&<>]").any() else v; cols.append([tpl[j] % (r, x) for r, x in zip(rows, v.tolist())])
                        elif j == 49: cols.append([tpl[j] % (r, x) for r, x in zip(rows, (v - epoch).dt.days.tolist())])
                        else: cols.append([tpl[j] % (r, x) for r, x in zip(rows, v.astype("int64").tolist())])
                    f.write("".join(f'<row r="{r}">{"".join(t)}</row>' for r, t in zip(rows, zip(*cols))).encode())
                f.write(("</sheetData>" + tail).encode())

def report_xlsx(ds):
    """Path of the Report Excel for these dates. Built once, then served from disk (cache)."""
    mt = os.path.getmtime(MAP) if os.path.exists(MAP) else 0
    key = hashlib.md5(("v3|%s|%s" % (mt, "|".join(f"{d}:{os.path.getmtime(os.path.join(DAILY, d + '.pkl'))}" for d in ds))).encode()).hexdigest()[:16]
    path = os.path.join(XL_DIR, key + ".xlsx")
    with _xl_lock:
        if not os.path.exists(path):
            build_report_xlsx([report(d) for d in ds], path + ".part"); os.replace(path + ".part", path)
            for old in sorted(glob.glob(os.path.join(XL_DIR, "*.xlsx")), key=os.path.getmtime)[:-12]: os.remove(old)
    return path

def prewarm(ds):
    """After an upload: build the Report (and its Excel) in the background so the first download is instant."""
    def run():
        for d in ds[-3:]:
            try: report_xlsx([d])
            except Exception: pass
    threading.Thread(target=run, daemon=True).start()

def xlsx(kind):
    import xlsxwriter
    from xlsxwriter.utility import xl_col_to_name as cn
    r = need()
    if r: return r
    title, loader, cols = KINDS[kind]
    if kind == "report":
        sel = picked()
        if not sel: return "No data in this date range", 404
        return send_file(report_xlsx(sel), as_attachment=True, download_name="Report.xlsx")
    b = io.BytesIO(); wb = xlsxwriter.Workbook(b, {"constant_memory": True, "in_memory": True, "default_date_format": "d-mmm-yy"})
    if kind == "daily":                 # 1 sheet = 1 date
        hd = wb.add_format({"bold": True, "bg_color": "#DDEBF7", "border": 1})
        for d in picked():
            ws = wb.add_worksheet(f"Daily Stock {d}"); ws.freeze_panes(1, 0); ws.write_row(0, 0, cols, hd); ws.autofilter(0, 0, 0, len(cols) - 1)
            ws.set_column(0, 0, 10); ws.set_column(1, 5, 20); ws.set_column(6, 13, 12); ws.set_column(14, len(cols), 6)
            for i, row in enumerate(view(load(d), cols).values.tolist(), 1): ws.write_row(i, 0, row)
    wb.close(); b.seek(0)
    return send_file(b, as_attachment=True, download_name=f"{title}.xlsx")

