def open_ui(url):
    """Own app window (no tabs/address bar) via Edge/Chrome --app; normal browser otherwise."""
    if os.name == "nt":
        import subprocess
        for e in (r"%ProgramFiles(x86)%\Microsoft\Edge\Application\msedge.exe", r"%ProgramFiles%\Microsoft\Edge\Application\msedge.exe", r"%ProgramFiles%\Google\Chrome\Application\chrome.exe",
                  r"%ProgramFiles(x86)%\Google\Chrome\Application\chrome.exe", r"%LOCALAPPDATA%\Google\Chrome\Application\chrome.exe"):
            p = os.path.expandvars(e)
            if os.path.exists(p): subprocess.Popen([p, "--app=" + url]); return
    webbrowser.open(url)

def wait_open(port, url):
    import socket, time
    for _ in range(120):                      # server ready hole-i window kholo (max 60 sec)
        with socket.socket() as k:
            if k.connect_ex(("127.0.0.1", port)) == 0: break
        time.sleep(0.5)
    open_ui(url)

